begin;
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('c1670000-0000-4000-8000-000000000001','detailed-author@mizyun.test'),('c1670000-0000-4000-8000-000000000002','detailed-viewer@mizyun.test');
update public.profiles set birth_year=1990 where id in ('c1670000-0000-4000-8000-000000000001','c1670000-0000-4000-8000-000000000002');
insert into public.workouts(id,user_id,name,notes,started_at,completed_at,details) values('d1670000-0000-4000-8000-000000000001','c1670000-0000-4000-8000-000000000001','Private title','Private notes',now()-interval '1 hour',now(),'{"workoutLifecycle":{"kind":"session"},"health":"private"}');
insert into public.exercises(id,user_id,name,instructions,metadata) values('e1670000-0000-4000-8000-000000000001','c1670000-0000-4000-8000-000000000001','Bench press','Private instruction','{"health":"private"}');
insert into public.workout_sets(id,user_id,workout_id,exercise_id,sequence,repetitions,load_kg,perceived_exertion,completed_at) values
 ('b1670000-0000-4000-8000-000000000001','c1670000-0000-4000-8000-000000000001','d1670000-0000-4000-8000-000000000001','e1670000-0000-4000-8000-000000000001',1,8,60,9,now()),
 ('b1670000-0000-4000-8000-000000000002','c1670000-0000-4000-8000-000000000001','d1670000-0000-4000-8000-000000000001','e1670000-0000-4000-8000-000000000001',2,12,100,10,null);
create temporary table expected_details as select '{"exercises":[{"name":"Bench press","sets":[{"setType":"normal","repetitions":8,"loadKg":60,"durationSeconds":null}]}]}'::jsonb value;
grant select on expected_details to authenticated;
create temporary table card_id(id uuid);
grant all on card_id to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='c1670000-0000-4000-8000-000000000001';
select * from public.community_save_profile('detail_author','Author','AU',null,false,true,'2026-09-30');
select is((select workout_details from public.community_publish_activity('d1670000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'a1670000-0000-4000-8000-000000000001',0,false)),null::jsonb,'Legacy publication stays minimal');
select is((select workout_details from public.community_publish_activity('d1670000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'a1670000-0000-4000-8000-000000000001',0,false)),null::jsonb,'Minimal legacy receipt retry remains compatible');
select is((select workout_details from public.community_publish_activity('d1670000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'a1670000-0000-4000-8000-000000000002',1,false,(select value from expected_details))),(select value from expected_details),'Detailed snapshot includes only completed allowed set fields');
insert into card_id select id from public.shared_activities;
select is((select item->'workout_details' from public.community_export_page('activities')),(select value from expected_details),'Owner export includes explicit snapshot');
select throws_ok($$select * from public.community_publish_activity('d1670000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'a1670000-0000-4000-8000-000000000003',2,false,(select value||'{"notes":"private"}' from expected_details))$$,'P0001','community_conflict','Direct RPC rejects extra private field');
update public.exercises set name='Changed privately' where id='e1670000-0000-4000-8000-000000000001';
select is((select workout_details from public.community_publish_activity('d1670000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'a1670000-0000-4000-8000-000000000002',1,false,(select value from expected_details))),(select value from expected_details),'Lost response retry returns original after private edit');
select throws_ok($$select * from public.community_publish_activity('d1670000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'a1670000-0000-4000-8000-000000000003',2,false,(select value from expected_details))$$,'P0001','community_conflict','Fresh stale confirmation cannot expose changed source');
select is((select workout_details from public.community_update_activity((select id from card_id),3600,2)),(select value from expected_details),'Narrow duration edit preserves detail snapshot');
set local request.jwt.claim.sub='c1670000-0000-4000-8000-000000000002';
select * from public.community_save_profile('detail_viewer','Viewer','VI',null,false,true,'2026-09-30');
select is((select count(*) from public.community_get_activity((select id from card_id))),0::bigint,'Outsider cannot read detailed card');
reset role;set local request.jwt.claim.role='service_role';
insert into public.community_relationships(follower_user_id,target_user_id,status) values('c1670000-0000-4000-8000-000000000002','c1670000-0000-4000-8000-000000000001','approved');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select workout_details from public.community_feed(20,null,null)),(select value from expected_details),'Approved follower sees exact published snapshot');
set local request.jwt.claim.sub='c1670000-0000-4000-8000-000000000001';
select public.community_unpublish_activity((select id from card_id),3);
set local request.jwt.claim.sub='c1670000-0000-4000-8000-000000000002';
select is((select count(*) from public.community_feed(20,null,null)),0::bigint,'Unpublish revokes details from follower feed');
select * from finish();
rollback;
